import { useState } from 'react';
import axios from 'axios';

export default function Sidebar({ docs, setDocs }) {
  const [status, setStatus] = useState('');
  const [statusType, setStatusType] = useState('');
  const [category, setCategory] = useState('通用');

  async function uploadFile(e) {
    const file = e.target.files[0];
    if (!file) return;
    setStatus('上传中…');
    setStatusType('');

    const formData = new FormData();
    formData.append('file', file);
    formData.append('category', category);

    try {
      const res = await axios.post('/upload', formData);
      if (res.data.error) {
        setStatus(`✗ ${res.data.error}`);
        setStatusType('err');
      } else {
        setStatus(`✓ ${res.data.chunks} 个片段已导入`);
        setStatusType('ok');
        setDocs(prev => [...prev, { name: file.name, category }]);
      }
    } catch {
      setStatus('✗ 上传失败，请检查服务');
      setStatusType('err');
    }
    e.target.value = '';
  }

  return (
    <div className="sidebar">
      <div className="panel">
        <div className="panel-header">上传文档</div>
        <div className="panel-body">
          <div className="upload-zone" onClick={() => document.getElementById('fileInput').click()}>
            <div className="upload-icon">📄</div>
            <div className="upload-label">点击上传 <strong>PDF / Word / TXT</strong></div>
            <input type="file" id="fileInput" accept=".pdf,.docx,.txt" onChange={uploadFile} style={{display:'none'}} />
          </div>
          <select className="select-field" value={category} onChange={e => setCategory(e.target.value)}>
            <option>通用</option>
            <option>人事政策</option>
            <option>法律法规</option>
            <option>财务制度</option>
            <option>技术文档</option>
          </select>
          <div className={`upload-status ${statusType}`}>{status}</div>
        </div>
      </div>

      <div className="panel">
        <div className="panel-header">已上传文档</div>
        <div className="panel-body">
          <div className="doc-list">
            {docs.length === 0
              ? <div className="doc-empty">暂无文档</div>
              : docs.map((d, i) => (
                <div className="doc-item" key={i}>
                  <span className="doc-badge">{d.category}</span>
                  <span className="doc-name" title={d.name}>{d.name}</span>
                </div>
              ))
            }
          </div>
        </div>
      </div>
    </div>
  );
}