import { useState, useRef, useEffect } from 'react';
import { marked } from 'marked';
import hljs from 'highlight.js';
import 'highlight.js/styles/github.css';

marked.setOptions({ breaks: true, gfm: true });
const renderer = new marked.Renderer();
renderer.code = (code, lang) => {
  const language = hljs.getLanguage(lang) ? lang : 'plaintext';
  const highlighted = hljs.highlight(typeof code === 'object' ? code.text : code, { language }).value;
  return `<pre><code class="hljs language-${language}">${highlighted}</code></pre>`;
};
marked.use({ renderer });

export default function ChatArea() {
  const [messages, setMessages] = useState([
    { role: 'ai', text: '你好！请先上传文档，然后就可以向我提问了。我会根据知识库内容为你解答。' }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const bottomRef = useRef(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  function handleKey(e) {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendQuestion();
    }
  }

  async function sendQuestion() {
    if (!input.trim() || loading) return;
    const question = input.trim();
    setInput('');
    setLoading(true);
    setMessages(prev => [...prev, { role: 'user', text: question }]);

    try {
      const res = await fetch('/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ question, session_id: 'default' })
      });

      const reader = res.body.getReader();
      const decoder = new TextDecoder();
      let full = '';
      let started = false;

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        full += decoder.decode(value);
        if (!started) {
          setMessages(prev => [...prev, { role: 'ai', text: full }]);
          started = true;
        } else {
          setMessages(prev => {
            const updated = [...prev];
            updated[updated.length - 1] = { role: 'ai', text: full };
            return updated;
          });
        }
      }

      if (!started) {
        setMessages(prev => [...prev, { role: 'ai', text: '未获取到回答，请重试。' }]);
      }
    } catch {
      setMessages(prev => [...prev, { role: 'ai', text: '请求失败，请检查服务是否启动。' }]);
    }

    setLoading(false);
  }

  return (
    <div className="chat-area">
      <div className="chat-messages">
        {messages.map((msg, i) => (
          <div className={`msg ${msg.role}`} key={i}>
            <div className={`avatar ${msg.role}`}>{msg.role === 'user' ? '我' : 'AI'}</div>
            <div className="bubble" dangerouslySetInnerHTML={{ __html: marked.parse(msg.text) }} />
          </div>
        ))}
        {loading && (
          <div className="msg ai">
            <div className="avatar ai">AI</div>
            <div className="bubble">
              <div className="typing-dots">
                <span /><span /><span />
              </div>
            </div>
          </div>
        )}
        <div ref={bottomRef} />
      </div>
      <div className="chat-input">
        <textarea
          value={input}
          onChange={e => setInput(e.target.value)}
          onKeyDown={handleKey}
          placeholder="输入问题，Enter 发送，Shift+Enter 换行…"
          rows={1}
        />
        <button className="send-btn" onClick={sendQuestion} disabled={loading}>
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <line x1="22" y1="2" x2="11" y2="13" />
            <polygon points="22 2 15 22 11 13 2 9 22 2" />
          </svg>
        </button>
      </div>
    </div>
  );
}